  // Sonderverlauf so setzen, dass der Titel (bei SMI auf Stützpunkt) dem relativen Verlauf rel folgt
  function extendRel(x, rel) {
    const sp = (x.special || [['1997-12-31', 1], [Y17, 1]]).filter(function (p) { return p[0] <= Y17; });
    const s0 = geo(sp, Y17), m0 = smi(Y17);
    rel.forEach(function (p) { sp.push([p[0], sig(s0 * p[1] * Math.pow(m0 / smi(p[0]), x.beta))]); });
    x.special = sp;
  }
  // Sonderverlauf aus absoluten Kursen (Lokalwährung)
  function fromPrices(x, px) {
    return px.map(function (p) { return [p[0], sig(p[1] / (x.base * Math.pow(smi(p[0]) / SMI_REF, x.beta)))]; });
  }
